"use client";

import Image from "next/image";
import { useState } from "react";

// Static maps generated by scripts/spatial_maps.py (NASA POWER, MERRA-2 0.5°×0.625°, 1992–2024).
const MAPS = [
  { id: "t2m-trend", label: "Tendencia T2M", file: "t2m_trend_1992_2024.png", width: 1630, height: 1197,
    note: "Cambio de la temperatura del aire a 2 m por década en cada celda. Los puntos marcan celdas cuyo intervalo individual excluye cero; son pruebas por celda sin corrección múltiple ni espacial: describen el patrón, no son evidencia conjunta." },
  { id: "t2m-anomaly", label: "2023–2024", file: "t2m_anomaly_2023_2024.png", width: 2213, height: 1130,
    note: "Anomalía anual de 2023 y 2024 respecto a la climatología mensual 1992–2021." },
  { id: "t2m-mean", label: "T2M media", file: "t2m_mean_1992_2024.png", width: 1412, height: 1159,
    note: "Temperatura media 1992–2024 por celda." },
  { id: "t2m-years", label: "33 años", file: "t2m_annual_anomaly_small_multiples.png", width: 2532, height: 2190,
    note: "Anomalía de cada año, 1992–2024, con la misma escala de color." },
  { id: "rain-trend", label: "Lluvia: tendencia", file: "prectotcorr_trend_pct_1992_2024.png", width: 1720, height: 1197,
    note: "Cambio de la precipitación corregida de POWER en % de su media por década. Mismas reservas que el mapa de tendencia de temperatura." },
  { id: "rain-anomaly", label: "Lluvia: 2023–2024", file: "prectotcorr_anomaly_2023_2024.png", width: 2186, height: 1130,
    note: "Anomalía de precipitación de 2023 y 2024 respecto a 1992–2021." },
] as const;

export function NasaMaps() {
  const [active, setActive] = useState<(typeof MAPS)[number]["id"]>("t2m-trend");
  const map = MAPS.find((m) => m.id === active)!;
  return (
    <div className="nasa-maps">
      <div className="nasa-map-tabs" role="tablist" aria-label="Mapa NASA 2D">
        {MAPS.map((m) => (
          <button key={m.id} role="tab" aria-selected={m.id === active} onClick={() => setActive(m.id)}>{m.label}</button>
        ))}
      </div>
      <a className="nasa-map-frame" href={`/maps/${map.file}`} target="_blank" rel="noreferrer" title="Abrir en tamaño completo">
        <Image src={`/maps/${map.file}`} alt={`${map.label}: mapa NASA POWER del norte y sur de México`} width={map.width} height={map.height}
          sizes="(max-width: 900px) 100vw, 50vw" priority={map.id === "t2m-trend"} />
      </a>
      <p className="nasa-map-note">
        {map.note} Fuente: NASA POWER (MERRA-2), celdas de 0.5°×0.625°, 1992–2024; las tres cajas del proyecto en magenta. Mapa precalculado: no cambia con el periodo elegido.
      </p>
    </div>
  );
}
